 async loadTemplates():Promise<void>{this.templateListLoading.set(true);try{this.templates.set(this.connected()?await this.api<SavedTemplate[]>('/templates'):readStorage<SavedTemplate[]>('templates',[]));}catch{this.notice.set('No se pudieron cargar las plantillas. Vuelve a intentarlo.');}finally{this.templateListLoading.set(false);}}
