 async readHtmlFile(event:Event):Promise<void>{const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;if(file.size>1000000){this.notice.set('El archivo HTML debe pesar menos de 1 MB.');return;}try{const text=decodeCsv(await file.arrayBuffer());if(text.length>250000)throw new Error('La plantilla supera los 250 000 caracteres.');this.templateSource.set(text);this.templateName.set(file.name.replace(/\.[^.]+$/,''));this.notice.set('HTML cargado. Revisa el código y pulsa Usar en una nueva campaña.');}catch(error:unknown){this.notice.set(error instanceof Error?error.message:'No se pudo leer el archivo HTML.');}}
