 if(this.connected()){const saved=await this.api<{id?:string}>('/templates'+(savedId?'/'+savedId:''),savedId?'PATCH':'POST',{name,html:imported.source});savedId=saved.id??savedId;}
 else{const items=readStorage<SavedTemplate[]>('templates',[]);if(items.length>=100&&!savedId)throw new Error('Tu biblioteca admite hasta 100 plantillas.');const saved={id:savedId||crypto.randomUUID(),name,document:{blocks:[],html:imported.source,subject:imported.title,preheader:imported.preheader}};const index=items.findIndex(item=>item.id===saved.id);if(index>=0)items[index]=saved;else items.push(saved);localStorage.setItem('mailcraft:templates',JSON.stringify(items));savedId=saved.id;}
 this.templateEditing.set(savedId);this.templateWarnings.set(imported.warnings);await this.loadTemplates();this.notice.set(this.connected()?'Plantilla guardada en tu biblioteca.':'Plantilla guardada en la demostración de este navegador.');
