 remember():void{this.history.update(items=>[...items.slice(-19),this.blocks()]);this.future.set([]);}
 undo():void{const history=this.history();const previous=history.at(-1);if(!previous)return;this.future.update(items=>[...items,this.blocks()]);this.blocks.set(previous);this.history.set(history.slice(0,-1));this.selected.set(previous[0]?.id??'');}
