 numberStyle(key:'fontSize'|'padding',value:string):void{const numeric=Number(value);if(!Number.isFinite(numeric))return;const minimum=key==='fontSize'?12:0;const maximum=key==='fontSize'?64:80;this.updateStyle({[key]:Math.min(maximum,Math.max(minimum,Math.round(numeric)))});}
