 addBlock(type:BlockType):void{this.remember();const id=crypto.randomUUID();this.blocks.update(items=>[...items,{id,type,content:type==='heading'?'Tu próxima gran idea':type==='button'?'Descubrir más':type==='text'?'Escribe algo que valga la pena abrir.':'',url:'https://example.com'}]);this.selected.set(id);}
