 createCampaign():void{this.campaignReview.set(null);this.reviewError.set('');this.audienceListIds.set([]);this.subjectVariant.set('');this.variantPercent.set(50);this.importedHtml.set('');this.templatePanel.set(false);this.remoteImages.set(false);this.testRequestKey.set('');this.testEmails.set([]);this.history.set([]);this.future.set([]);const id=crypto.randomUUID();const block:EmailBlock={id:crypto.randomUUID(),type:'heading',content:'Tu próxima gran idea'};this.campaigns.update(items=>[{id,name:'Nueva campaña',subject:'',updated:'Ahora',blocks:[block],preheader:'',audienceListIds:[]},...items]);this.activeCampaign.set(id);this.selected.set(block.id);this.subject.set('');this.preheader.set('');this.blocks.set([block]);this.page.set('Editor visual');this.persist();}
 async openCampaign(id:string):Promise<void>{this.campaignReview.set(null);this.reviewError.set('');this.testRequestKey.set('');this.testEmails.set([]);this.history.set([]);this.future.set([]);const campaign=this.campaigns().find(c=>c.id===id);if(!campaign)return;this.activeCampaign.set(id);this.importedHtml.set(campaign.html??'');this.remoteImages.set(false);this.templatePanel.set(false);this.subject.set(campaign.subject);this.subjectVariant.set(campaign.subjectVariant??'');this.variantPercent.set(campaign.variantPercent??50);this.preheader.set(campaign.preheader);this.blocks.set(campaign.blocks);this.selected.set(campaign.blocks[0]?.id??'');this.audienceListIds.set(campaign.audienceListIds??[]);if(this.connected())try{const saved=await this.api<{audienceListIds:string[]}>('/campaigns/'+id);this.audienceListIds.set(saved.audienceListIds);this.campaigns.update(items=>items.map(item=>item.id===id?{...item,audienceListIds:saved.audienceListIds}:item));}catch{this.notice.set('No se pudo cargar la audiencia guardada. Vuelve a abrir la campaña.');}this.page.set('Editor visual');}
 toggleAudienceList(id:string,checked:boolean):void{this.audienceListIds.update(ids=>checked?[...new Set([...ids,id])]:ids.filter(value=>value!==id));this.campaignReview.set(null);}
 async save():Promise<boolean>{
 if(this.sessionExpired()){this.page.set('Cuenta');this.notice.set('Inicia sesión para guardar los cambios.');return false;}
 const existing=this.campaigns().find(campaign=>campaign.id===this.activeCampaign());if(this.connected()&&existing?.status&&existing.status!=='draft'){this.notice.set('Esta campaña ya salió del estado de borrador y no se puede editar.');return false;}
 if(this.saving())return false;this.saving.set(true);
 try{
 if(!this.activeCampaign()){const id=crypto.randomUUID();this.activeCampaign.set(id);this.campaigns.update(items=>[{id,name:'Nueva campaña',subject:'',preheader:'',updated:'Ahora',blocks:[]},...items]);}
 this.campaigns.update(items=>items.map(c=>c.id===this.activeCampaign()?{...c,name:this.subject()||'Campaña sin título',subject:this.subject(),subjectVariant:this.subjectVariant().trim()||undefined,variantPercent:this.subjectVariant().trim()?this.variantPercent():undefined,preheader:this.preheader(),blocks:this.blocks(),html:this.importedHtml(),audienceListIds:this.audienceListIds(),updated:new Date().toLocaleDateString('es-PE')}:c));
 if(this.connected()){
 const id=this.activeCampaign(),campaign=this.campaigns().find(c=>c.id===id);if(!campaign)return false;
 const payload={name:campaign.name,subject:campaign.subject,subjectVariant:campaign.subjectVariant??null,variantPercent:campaign.subjectVariant?campaign.variantPercent??50:null,preheader:campaign.preheader,document:{blocks:campaign.blocks,...(campaign.html?{html:campaign.html}:{})},audienceListIds:this.audienceListIds()};
 if(this.remoteIds.has(id))await this.api('/campaigns/'+id,'PATCH',payload);
 else{const result=await this.api<ServerCampaign>('/campaigns','POST',payload);this.remoteIds.add(result.id);this.campaigns.update(items=>items.map(c=>c.id===id?{...c,id:result.id}:c));this.activeCampaign.set(result.id);}
 this.notice.set('Diseño guardado en tu espacio de trabajo.');
 }else{this.persist();this.notice.set('Diseño guardado en este navegador.');}return true;
 }catch{this.notice.set('No se pudo guardar en el servidor. Tu diseño sigue abierto; vuelve a intentarlo.');return false;}
 finally{this.saving.set(false);}}
 persist():void{if(this.connected())return;try{localStorage.setItem('mailcraft:campaigns',JSON.stringify(this.campaigns()));localStorage.setItem('mailcraft:contacts',JSON.stringify(this.contacts()));}catch{this.notice.set('No se pudo guardar. Comprueba el espacio disponible del navegador.');}}
 download():void{const url=URL.createObjectURL(new Blob([this.html()],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='mailcraft-email.html';a.click();URL.revokeObjectURL(url);this.notice.set('HTML exportado. Configura la URL de baja antes de enviar.');}
 async addContact(name:string,email:string):Promise<'added'|'duplicate'|'invalid'|'failed'>{
 if(this.sessionExpired()){this.notice.set('Inicia sesión para añadir contactos.');return 'failed';}
 if(!this.consentConfirmed()){this.notice.set('Confirma que cuentas con consentimiento para añadir contactos.');return 'invalid';}
 const normalized=email.trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalized)){this.notice.set('Introduce un correo electrónico válido.');return 'invalid';}
 if(this.contacts().some(c=>c.email===normalized)){this.notice.set('Este contacto ya existe. No se modificó su suscripción.');return 'duplicate';}
 if(this.connected()){try{const saved=await this.api<ServerContact>('/contacts','POST',{firstName:name.trim()||'Sin nombre',email:normalized,consent:true});this.contacts.update(items=>[...items,{id:saved.id,name:saved.firstName,email:saved.email,status:saved.status}]);await this.loadContacts(1);this.notice.set('Contacto guardado en tu espacio de trabajo.');return 'added';}catch{this.notice.set('No se pudo guardar el contacto. Revisa tu sesión e inténtalo de nuevo.');return 'failed';}}
 this.contacts.update(items=>[...items,{id:crypto.randomUUID(),name:name.trim()||'Sin nombre',email:normalized,status:'subscribed'}]);this.persist();this.notice.set('Contacto añadido en este navegador.');return 'added';}
 async importCsv(event:Event):Promise<void>{const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;input.value='';if(file.size>5000000){this.notice.set('El archivo debe pesar menos de 5 MB.');return;}this.csvTable.set(null);try{this.csvSource=decodeCsv(await file.arrayBuffer());this.csvSeparator.set('auto');this.parseImport();if(this.connected())this.contactFields.set(await this.api<ContactField[]>('/contacts/fields'));else this.contactFields.set(readStorage<ContactField[]>('contact-fields',[]));}catch(error:unknown){this.notice.set(error instanceof Error?error.message:'No se pudo leer el archivo.');}}
 parseImport():void{try{const separator=this.csvSeparator();const table=parseCsv(this.csvSource,separator==='auto'?undefined:separator as CsvDelimiter);this.csvTable.set(table);this.csvMappings.set(table.headers.map(header=>{const normalized=header.toLowerCase().trim();return {header,target:['email','correo','correo electrónico','e-mail'].includes(normalized)?'email':['nombre','name','first_name','firstname'].includes(normalized)?'name':'skip',label:header};}));this.importProgress.set(0);this.notice.set('Archivo leído. Revisa el mapeo de cada columna antes de importar.');}catch(error:unknown){this.csvTable.set(null);this.notice.set(error instanceof Error?error.message:'No se pudo leer el CSV.');}}
