 async loadCampaigns(page:number):Promise<void>{const sequence=++this.campaignRequest,tenant=this.tenantId();this.campaignLoading.set(true);try{const query=new URLSearchParams({page:String(page),pageSize:'25',q:this.search()});const result=await this.api<{data:ServerCampaign[];meta:PageMeta}>('/campaigns/page?'+query);if(sequence!==this.campaignRequest||tenant!==this.tenantId())return;this.campaignMeta.set(result.meta);this.campaigns.set(result.data.map(c=>({id:c.id,name:c.name,subject:c.subject,subjectVariant:c.subjectVariant??undefined,variantPercent:c.variantPercent??undefined,preheader:c.preheader,blocks:c.document.blocks??[],html:c.document.html??'',audienceListIds:c.audienceListIds??[],updated:new Date(c.createdAt).toLocaleDateString('es-PE'),status:c.status,scheduledAt:c.scheduledAt??undefined,timeZone:c.timeZone})));result.data.forEach(c=>this.remoteIds.add(c.id));}catch(error:unknown){if(sequence===this.campaignRequest)this.notice.set(error instanceof Error?error.message:'No se pudieron cargar las campañas.');}finally{if(sequence===this.campaignRequest)this.campaignLoading.set(false);}}
