 async loadContacts(page:number,forceRemote=false):Promise<void>{if(!this.connected()&&!forceRemote){this.contactPage.set(page);return;}const sequence=++this.contactRequest,tenant=this.tenantId();this.contactLoading.set(true);this.contactError.set('');try{const query=new URLSearchParams({page:String(page),pageSize:String(this.contactPageSize()),q:this.contactQuery(),status:this.contactStatus(),archived:String(this.contactArchive()),listId:this.contactList()});const result=await this.api<ContactPage>('/contacts/page?'+query);if(sequence!==this.contactRequest||tenant!==this.tenantId())return;this.contactPage.set(result.meta.page);this.remoteContactMeta.set(result.meta);this.contactTotal.set(result.meta.total);this.subscribedTotal.set(result.subscribed);this.contacts.set(result.data.map(c=>({id:c.id,name:c.firstName,email:c.email,status:c.status,customFields:c.attributes?.customFields??{},archivedAt:c.archivedAt})));}catch(error:unknown){if(sequence===this.contactRequest&&tenant===this.tenantId())throw error;}finally{if(sequence===this.contactRequest)this.contactLoading.set(false);}}
