 async saveContactView():Promise<void>{if(this.viewBusy())return;this.viewBusy.set(true);this.viewError.set('');try{const name=this.viewName().trim();if(!name||name.length>80)throw new Error('Escribe un nombre de hasta 80 caracteres.');const payload={name,filters:{q:this.contactQuery(),status:this.contactStatus(),archived:this.contactArchive(),pageSize:this.contactPageSize(),...(this.contactList()?{listId:this.contactList()}:{})},columns:this.visibleFields().map(field=>field.key)};let id=this.viewEditing();if(this.connected()){const result=await this.api<{id?:string}>('/contact-views'+(id?'/'+id:''),id?'PATCH':'POST',payload);id=result.id??id;}else{const items=readStorage<ContactView[]>('contact-views',[]);if(!id&&items.length>=20)throw new Error('Puedes guardar hasta 20 vistas.');id=id||crypto.randomUUID();const index=items.findIndex(view=>view.id===id),record={id,...payload};if(index>=0)items[index]=record;else items.push(record);localStorage.setItem('mailcraft:contact-views',JSON.stringify(items));}this.viewDialog?.nativeElement.close();await this.loadContactResources();this.activeContactView.set(id);this.notice.set('Vista guardada con tus filtros, columnas y tamaño de página.');}catch(error:unknown){this.viewError.set(error instanceof Error?error.message:'No se pudo guardar la vista.');}finally{this.viewBusy.set(false);}}
