 async openRecord(kind:'contact'|'list'|'field',item?:Contact|ContactList|ContactField):Promise<void>{const contact=kind==='contact'?item as Contact|undefined:undefined,field=kind==='field'?item as ContactField|undefined:undefined,list=kind==='list'?item as ContactList|undefined:undefined;this.recordError.set('');this.listTarget.set('');this.recordEditor.set({kind,id:contact?.id??list?.id??field?.key??'',name:contact?.name??list?.name??field?.label??'',email:contact?.email??'',values:{...contact?.customFields},listIds:contact?.id?this.lists().filter(list=>list.contactIds?.includes(contact.id??'')).map(list=>list.id):[]});if(kind==='contact'&&contact?.id&&this.connected()){try{const detail=await this.api<ServerContact>('/contacts/'+contact.id);this.recordEditor.update(editor=>editor&&editor.id===contact.id?{...editor,listIds:detail.memberships?.map(item=>item.listId)??[]}:editor);}catch{this.recordError.set('No se pudo cargar el detalle completo. Vuelve a intentarlo.');}}setTimeout(()=>this.recordDialog?.nativeElement.showModal(),0);}
